#!/bin/bash
cd /testbed
source /opt/conda/bin/activate testbed

# H1: rewrite every file the upstream test patch touches to its upstream version.
restore_upstream_tests() {
    rm -rf -- synapse/tests/test_cortex.py synapse/tests/test_lib_storm.py &&
        git --literal-pathspecs checkout -q 82966be7ae8b614ae15eb42b3bf7b8306e5604bf -- synapse/tests/test_cortex.py synapse/tests/test_lib_storm.py &&
        git apply /tests/upstream_tests.patch
}

mkdir -p /logs/verifier
if restore_upstream_tests && pytest --no-header -rA --tb=line --color=no -p no:cacheprovider -W ignore::DeprecationWarning synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_del_tufo synapse/tests/test_lib_storm.py::StormTest::test_storm_delnode_caching synapse/tests/test_cortex.py::CortexTest::test_cortex_addmodel synapse/tests/test_cortex.py::CortexTest::test_cortex_by_type synapse/tests/test_cortex.py::CortexTest::test_cortex_bytype synapse/tests/test_cortex.py::CortexTest::test_cortex_caching synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_add_tufo synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_atlimit synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_new synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_oneref synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_set synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_tags synapse/tests/test_cortex.py::CortexTest::test_cortex_caching_under_limit synapse/tests/test_cortex.py::CortexTest::test_cortex_choptag synapse/tests/test_cortex.py::CortexTest::test_cortex_comp synapse/tests/test_cortex.py::CortexTest::test_cortex_dict synapse/tests/test_cortex.py::CortexTest::test_cortex_enforce synapse/tests/test_cortex.py::CortexTest::test_cortex_events synapse/tests/test_cortex.py::CortexTest::test_cortex_fire_set synapse/tests/test_cortex.py::CortexTest::test_cortex_getbytag synapse/tests/test_cortex.py::CortexTest::test_cortex_ingest synapse/tests/test_cortex.py::CortexTest::test_cortex_isnew synapse/tests/test_cortex.py::CortexTest::test_cortex_lmdb synapse/tests/test_cortex.py::CortexTest::test_cortex_local synapse/tests/test_cortex.py::CortexTest::test_cortex_minmax synapse/tests/test_cortex.py::CortexTest::test_cortex_minmax_epoch synapse/tests/test_cortex.py::CortexTest::test_cortex_modlrevs synapse/tests/test_cortex.py::CortexTest::test_cortex_modlvers synapse/tests/test_cortex.py::CortexTest::test_cortex_module synapse/tests/test_c